const keys=new Set();let started=false,inCar=false,playerYaw=0,carYaw=0,carSpeed=0,walkVelocity=0,jump=0,jumpVelocity=0,cash=2450,objective=1,lookYaw=0,lookPitch=.16,dragging=false,lastPointer={x:0,y:0},toastTimer=0;
