function moveSafe(pos,dx,dz,r=.7){let nx=clamp(pos.x+dx,-315,315),nz=clamp(pos.z+dz,-315,315);if(!closeToBuilding(nx,nz,r))pos.set(nx,0,nz);else{if(!closeToBuilding(nx,pos.z,r))pos.x=nx;if(!closeToBuilding(pos.x,nz,r))pos.z=nz}}
function nearestCar(){return player.position.distanceTo(car.position)}
function doAction(){if(!started)return;if(!inCar&&nearestCar()<5){inCar=true;player.visible=false;carSpeed=0;toast('CLASSIC COUPE · READY');document.querySelector('#speedbox').classList.add('visible');document.querySelector('#help').innerHTML='<b>W / ↑</b> ACCELERATE &nbsp;·&nbsp; <b>S / ↓</b> REVERSE<br><b>A / D</b> STEER &nbsp;·&nbsp; <b>E</b> EXIT &nbsp;·&nbsp; <b>SPACE</b> BRAKE'}else if(inCar&&Math.abs(carSpeed)<2){inCar=false;player.visible=true;player.position.set(car.position.x+Math.cos(carYaw)*2,0,car.position.z+Math.sin(carYaw)*2);playerYaw=carYaw;document.querySelector('#speedbox').classList.remove('visible');document.querySelector('#help').innerHTML='<b>W A S D</b> MOVE &nbsp;·&nbsp; <b>SHIFT</b> RUN &nbsp;·&nbsp; <b>E</b> ENTER RIDE<br><b>MOUSE</b> LOOK &nbsp;·&nbsp; <b>SPACE</b> JUMP / BRAKE';toast('BACK ON FOOT')}}
function activate(){if(started)return;started=true;document.querySelector('#intro').classList.add('hide');toast('WELCOME TO LOS SANTOS');canvas.requestPointerLock?.()}
document.querySelector('#play').addEventListener('click',activate);
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k==='e'&&!e.repeat)doAction();if(k==='escape'&&started)document.exitPointerLock?.()});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
