canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);
for(const btn of document.querySelectorAll('[data-key]')){const k=btn.dataset.key;const on=e=>{e.preventDefault();keys.add(k);btn.classList.add('down')},off=e=>{e.preventDefault();keys.delete(k);btn.classList.remove('down')};btn.addEventListener('pointerdown',on);btn.addEventListener('pointerup',off);btn.addEventListener('pointerleave',off);btn.addEventListener('pointercancel',off)}
document.querySelector('#horn').addEventListener('click',()=>toast('HONK!'));

function drawMap(){const c=document.querySelector('#map'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#192628';ctx.fillRect(0,0,w,h);const p=inCar?car.position:player.position,scale=.48,ox=w/2-p.x*scale,oy=h/2-p.z*scale;ctx.strokeStyle='#59615c';ctx.lineWidth=7;for(let n=-GRID;n<=GRID;n++){const q=n*STEP*scale;ctx.beginPath();ctx.moveTo(ox+q,0);ctx.lineTo(ox+q,h);ctx.stroke();ctx.beginPath();ctx.moveTo(0,oy+q);ctx.lineTo(w,oy+q);ctx.stroke()}ctx.strokeStyle='#d5b875';ctx.lineWidth=1;for(let n=-GRID;n<=GRID;n++){let q=n*STEP*scale;for(let d=-300;d<300;d+=16){let t=d*scale;ctx.beginPath();ctx.moveTo(ox+t,oy+q);ctx.lineTo(ox+t+2,oy+q);ctx.stroke();ctx.beginPath();ctx.moveTo(ox+q,oy+t);ctx.lineTo(ox+q,oy+t+2);ctx.stroke()}}const g=goals[goalIndex];ctx.fillStyle='#ffc653';ctx.beginPath();ctx.arc(ox+g.x*scale,oy+g.z*scale,5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffc65366';ctx.beginPath();ctx.arc(ox+g.x*scale,oy+g.z*scale,9,0,Math.PI*2);ctx.stroke();ctx.save();ctx.translate(w/2,h/2);ctx.rotate(-(inCar?carYaw:playerYaw));ctx.fillStyle=inCar?'#ff785f':'#9ae3c4';ctx.beginPath();ctx.moveTo(0,-8);ctx.lineTo(6,7);ctx.lineTo(0,4);ctx.lineTo(-6,7);ctx.closePath();ctx.fill();ctx.restore()}

const clock=new THREE.Clock();let camTarget=new THREE.Vector3();
