 if(started){
  if(inCar){const throttle=(forward?1:0)-(back?1:0);carSpeed+=throttle*dt*14;carSpeed*=Math.pow(brake?.12:.985,dt*60);carSpeed=clamp(carSpeed,-8,26);if(Math.abs(carSpeed)>.2){const steering=(right?1:0)-(left?1:0);carYaw+=steering*dt*(1.55*Math.min(1,Math.abs(carSpeed)/5))*Math.sign(carSpeed);const dx=Math.sin(carYaw)*carSpeed*dt,dz=-Math.cos(carYaw)*carSpeed*dt;const old=car.position.clone();moveSafe(car.position,dx,dz,1.3);if(car.position.distanceTo(old)<Math.abs(dx+dz)*.28)carSpeed*=-.2;car.rotation.y=carYaw}document.querySelector('#speed').textContent=String(Math.round(Math.abs(carSpeed)*2.1)).padStart(2,'0');
